// Load environment variables
require('dotenv').config();

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const morgan = require('morgan');

const app = express();

// Validate required environment variables
const requiredEnvVars = [];
const missingEnvVars = requiredEnvVars.filter(envVar => !process.env[envVar]);
if (missingEnvVars.length > 0) {
  console.error(`Missing required environment variables: ${missingEnvVars.join(', ')}`);
  process.exit(1);
}

// Configuration from environment variables
const config = {
  port: parseInt(process.env.PORT || '3000', 10),
  nodeEnv: process.env.NODE_ENV || 'development',
  host: process.env.HOST || 'localhost',
  allowedOrigins: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  rateLimit: {
    windowMs: parseInt(process.env.RATE_LIMIT_WINDOW_MS || '900000', 10), // 15 minutes default
    max: parseInt(process.env.RATE_LIMIT_MAX_REQUESTS || '100', 10)
  }
};

// Security middleware
app.use(helmet());
app.use(cors({
  origin: config.allowedOrigins,
  credentials: true
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: config.rateLimit.windowMs,
  max: config.rateLimit.max,
  message: 'Too many requests from this IP, please try again later.'
});
app.use(limiter);

// Body parser with limits
app.use(express.json({ limit: process.env.BODY_SIZE_LIMIT || '10kb' }));
app.use(express.urlencoded({ extended: true, limit: process.env.BODY_SIZE_LIMIT || '10kb' }));

// Logging (only in development/production, not in test)
if (config.nodeEnv !== 'test') {
  app.use(morgan(config.nodeEnv === 'development' ? 'dev' : 'combined'));
}

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: config.nodeEnv
  });
});

// Users endpoint - In production, this should:
// 1. Require authentication
// 2. Fetch from database using DATABASE_URL from env
// 3. Implement pagination
app.get('/users', (req, res) => {
  // TODO: Add authentication middleware
  // TODO: Connect to database using process.env.DATABASE_URL

  // Temporary mock data - should be replaced with database query
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  res.json(users);
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error(err.stack);

  // Don't leak error details in production
  const errorResponse = config.nodeEnv === 'production' 
    ? { error: 'Internal server error' }
    : { error: err.message, stack: err.stack };

  res.status(err.statusCode || 500).json(errorResponse);
});

// Start server only if not being required as a module
if (require.main === module) {
  app.listen(config.port, config.host, () => {
    console.log(`Server running on ${config.host}:${config.port} in ${config.nodeEnv} mode`);
  });
}

module.exports = app;

