STRIPE_WEBHOOK_SECRET=

# Logging
LOG_LEVEL=info
LOG_FORMAT=json

# Feature Flags
ENABLE_SWAGGER=false
ENABLE_METRICS=true
USE_MOCK_DATA=true
```

